    [Fact]
    public async Task ToriiClientPreservesBasePathPrefixAndNormalizesTrailingSlash()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("ok"),
        });

        using var client = new ToriiClient(new Uri("https://torii.example/root/torii"), new HttpClient(handler));
        var health = await client.GetHealthAsync(cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal("ok", health);
        Assert.Equal("https://torii.example/root/torii/", client.BaseUri.AbsoluteUri);
        Assert.Equal("/root/torii/v1/health", handler.LastRequest!.RequestUri!.AbsolutePath);
    }

    [Fact]
    public async Task GetJsonDocumentAsyncAddsBearerAndCanonicalHeaders()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("{\"ok\":true}"),
        });
        var options = new ToriiClientOptions
        {
            BearerToken = "dev-token",
            NetworkId = OnboardingFixtureNetworkId,
            CanonicalRequestCredentials = new CanonicalRequestCredentials(
                CanonicalAccountId,
                CanonicalPrivateKeySeed),
        };
        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler),
            options,
            TransactionSubmissionTransportAssurance.OneShotWithoutRedirectsOrRetries);
        using var document = await client.GetJsonDocumentAsync("/v1/query", "gas_units=100&cursor_mode=stored", cancellationToken: TestContext.Current.CancellationToken);

        Assert.True(document.RootElement.GetProperty("ok").GetBoolean());
        Assert.Equal("Bearer", handler.LastRequest!.Headers.Authorization?.Scheme);
        Assert.Equal("dev-token", handler.LastRequest.Headers.Authorization?.Parameter);
        Assert.True(handler.LastRequest.Headers.Contains("X-Iroha-Account"));
        Assert.True(handler.LastRequest.Headers.Contains("X-Iroha-Signature"));
        Assert.Equal(
            AccountAddress.Parse(CanonicalAccountId, AccountAddress.DefaultChainDiscriminant).CanonicalHex,
            Assert.Single(handler.LastRequest.Headers.GetValues("X-Iroha-Account")));
        Assert.All(
            Assert.Single(handler.LastRequest.Headers.GetValues("X-Iroha-Nonce")),
            character => Assert.False(char.IsWhiteSpace(character)));
        Assert.Equal("/v1/query?gas_units=100&cursor_mode=stored", handler.LastRequest.RequestUri!.PathAndQuery);
    }

    [Fact]
    public async Task GetJsonDocumentAsyncRejectsDuplicateJsonResponseKeys()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("""{"ok":true,"ok":false}"""),
        });
        using var client = new ToriiClient(new Uri("https://torii.example"), new HttpClient(handler));

        var error = await Assert.ThrowsAsync<JsonException>(() =>
            client.GetJsonDocumentAsync("/v1/query", "gas_units=100", cancellationToken: TestContext.Current.CancellationToken));

        Assert.Contains("ok must not appear more than once", error.Message);
        Assert.Equal("/v1/query?gas_units=100", handler.LastRequest!.RequestUri!.PathAndQuery);
    }

    [Fact]
    public async Task GetJsonDocumentAsyncRejectsUndeclaredResponsesBeyondEightMiB()
    {
        using var handler = new RecordingHandler(_ =>
        {
            var content = new StreamContent(new MemoryStream(
                new byte[8 * 1024 * 1024 + 1],
                writable: false));
            content.Headers.ContentLength = null;
            return new HttpResponseMessage(HttpStatusCode.OK) { Content = content };
        });
        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler));

        var error = await Assert.ThrowsAsync<InvalidDataException>(() =>
            client.GetJsonDocumentAsync(
                "/v1/query",
                cancellationToken: TestContext.Current.CancellationToken));

        Assert.Contains("8388608-byte limit", error.Message, StringComparison.Ordinal);
    }

