    [Theory]
    [InlineData("", "empty or whitespace")]
    [InlineData(" ", "empty or whitespace")]
    [InlineData(" dev-token", "surrounding whitespace")]
    [InlineData("dev-token ", "surrounding whitespace")]
    [InlineData("dev token", "whitespace")]
    [InlineData("dev\u00A0token", "whitespace")]
    [InlineData("dev-token\u0001", "control characters")]
    [InlineData("=", "HTTP bearer token")]
    [InlineData("dev=token", "trailing-only")]
    [InlineData("dev=token=", "trailing-only")]
    [InlineData("dev:token", "HTTP bearer token")]
    [InlineData("dev,token", "HTTP bearer token")]
    [InlineData("dev;token", "HTTP bearer token")]
    [InlineData("dev(token)", "HTTP bearer token")]
    [InlineData("dev[token]", "HTTP bearer token")]
    [InlineData("dev\\token", "HTTP bearer token")]
    [InlineData("dev\"token", "HTTP bearer token")]
    [InlineData("dev?token", "HTTP bearer token")]
    [InlineData("dev@token", "HTTP bearer token")]
    [InlineData("dev\u007Ftoken", "control characters")]
    [InlineData("devétoken", "HTTP bearer token")]
    public async Task SendAsyncRejectsNonExactBearerTokensBeforeDispatchAndCanonicalSigning(
        string bearerToken,
        string expectedMessage)
    {
        using var handler = new RecordingHandler(_ =>
            throw new InvalidOperationException("non-exact bearer token reached HTTP dispatch"));
        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler),
            new ToriiClientOptions
            {
                BearerToken = bearerToken,
                NetworkId = OnboardingFixtureNetworkId,
                CanonicalRequestCredentials = new CanonicalRequestCredentials(
                    CanonicalAccountId,
                    CanonicalPrivateKeySeed),
            },
            TransactionSubmissionTransportAssurance.OneShotWithoutRedirectsOrRetries);

        var error = await Assert.ThrowsAsync<ArgumentException>(() =>
            client.GetJsonDocumentAsync("/v1/query", "gas_units=100", cancellationToken: TestContext.Current.CancellationToken));

        Assert.Equal("BearerToken", error.ParamName);
        Assert.Contains(expectedMessage, error.Message);
        Assert.Null(handler.LastRequest);
    }

