    [Fact]
    public async Task GetNodeCapabilitiesAsyncDeserializesTypedResponse()
    {
        const string responseBody = """
            {
              "abi_version": 1,
              "data_model_version": 1,
              "signed_transaction_schema_hash_hex": "eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
              "crypto": {
                "curves": {
                  "allowed_curve_bitmap": [26],
                  "allowed_curve_ids": [1, 3, 4],
                  "registry_version": 1
                },
                "sm": {
                  "acceleration": {
                    "neon_sm3": false,
                    "neon_sm4": false,
                    "policy": "scalar-only",
                    "scalar": true
                  },
                  "allowed_signing": ["ed25519", "secp256k1", "bls_normal"],
                  "default_hash": "blake2b-256",
                  "enabled": false,
                  "openssl_preview": false,
                  "sm2_distid_default": "1234567812345678"
                }
              },
              "query": {
                "aggregate": {
                  "exact_results": true,
                  "supported_resources": ["domains", "accounts", "asset_definitions", "nfts", "rwas", "account_assets", "asset_holders", "repo_agreements"],
                  "v1": true
                },
                "projection": {
                  "archive_export_v1": true,
                  "archive_version": 1,
                  "blob_class_custom_id": 1001,
                  "checkpoint_contract_v1": true,
                  "codec": "application/x-iroha-query-shard+norito+zstd",
                  "compression": "zstd",
                  "da_v1_enabled": false,
                  "default_partition_count": 4096,
                  "export_supported_resources": ["accounts"],
                  "latest_checkpoint_block_hash_hex": "8888888888888888888888888888888888888888888888888888888888888888",
                  "latest_checkpoint_indexed_height": 42,
                  "metadata_keys": ["query_projection.locator", "query_projection.resource", "query_projection.partition_id", "query_projection.asset_definition_id", "query_projection.indexed_height", "query_projection.indexed_block_hash_hex", "query_projection.row_count", "query_projection.rowset_codec", "query_projection.rowset_hash_hex", "query_projection.emitted_at_unix"],
                  "rowset_codec": "application/x-iroha-query-shard-rowset+norito",
                  "schema_version": 1,
                  "shard_catalog_v1": true
                }
              }
            }
            """;

        using var handler = new RecordingHandler(_ => JsonResponse(responseBody));

        using var client = CreateRuntimeAuthenticatedClient(handler);
        var capabilities = await client.GetNodeCapabilitiesAsync(cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(1, capabilities.AbiVersion);
        Assert.Equal(1, capabilities.DataModelVersion);
        Assert.Equal(SignedTransactionSchemaHashHex, capabilities.SignedTransactionSchemaHashHex);
        var allowedSigning = Assert.IsType<string[]>(capabilities.Crypto.Sm.AllowedSigning);
        var allowedCurveIds = Assert.IsType<int[]>(capabilities.Crypto.Curves.AllowedCurveIds);
        var allowedCurveBitmap = Assert.IsType<ulong[]>(capabilities.Crypto.Curves.AllowedCurveBitmap);
        var supportedResources = Assert.IsType<string[]>(capabilities.Query.Aggregate.SupportedResources);
        var metadataKeys = Assert.IsType<string[]>(capabilities.Query.Projection.MetadataKeys);
        var exportSupportedResources = Assert.IsType<string[]>(capabilities.Query.Projection.ExportSupportedResources);
        Assert.Equal(3, allowedCurveIds.Length);
        Assert.Contains("ed25519", allowedSigning);
        Assert.True(capabilities.Query.Aggregate.V1);
        Assert.Equal("application/x-iroha-query-shard+norito+zstd", capabilities.Query.Projection.Codec);
        allowedSigning[0] = "mutated";
        allowedCurveIds[0] = 99;
        allowedCurveBitmap[0] = 0;
        supportedResources[0] = "mutated";
        metadataKeys[0] = "mutated";
        exportSupportedResources[0] = "mutated";
        Assert.Contains("ed25519", capabilities.Crypto.Sm.AllowedSigning);
        Assert.Equal(1, capabilities.Crypto.Curves.AllowedCurveIds[0]);
        Assert.Equal((ulong)26, capabilities.Crypto.Curves.AllowedCurveBitmap[0]);
        Assert.Equal("domains", capabilities.Query.Aggregate.SupportedResources[0]);
        Assert.Equal(8, capabilities.Query.Aggregate.SupportedResources.Count);
        Assert.Equal("query_projection.locator", capabilities.Query.Projection.MetadataKeys[0]);
        Assert.Equal("accounts", capabilities.Query.Projection.ExportSupportedResources[0]);
        Assert.Equal("/v1/node/capabilities", handler.LastRequest!.RequestUri!.AbsolutePath);
    }

    [Fact]
    public void NodeCapabilitiesListsSnapshotInitAndAccessValues()
    {
        string[] allowedSigning = ["ed25519", "secp256k1"];
        var sm = new ToriiNodeSmCapabilities
        {
            Enabled = false,
            DefaultHash = "blake2b-256",
            AllowedSigning = allowedSigning,
            Sm2DistidDefault = "1234567812345678",
            OpensslPreview = false,
            Acceleration = new ToriiNodeSmAcceleration { Scalar = true, Policy = "scalar-only" },
        };
        int[] allowedCurveIds = [1, 3, 4];
        ulong[] allowedCurveBitmap = [26];
        var curves = new ToriiNodeCurveCapabilities
        {
            RegistryVersion = 1,
            AllowedCurveIds = allowedCurveIds,
            AllowedCurveBitmap = allowedCurveBitmap,
        };
        string[] supportedResources = ["accounts"];
        var aggregate = new ToriiNodeAggregateQueryCapabilities
        {
            V1 = true,
            ExactResults = true,
            SupportedResources = supportedResources,
        };
        string[] metadataKeys = ["query_projection.locator"];
        string[] exportSupportedResources = ["accounts"];
        var projection = new ToriiNodeProjectionCapabilities
        {
            CheckpointContractV1 = true,
            ShardCatalogV1 = true,
            ArchiveExportV1 = true,
            ArchiveVersion = 1,
            SchemaVersion = 1,
            BlobClassCustomId = 1001,
            Codec = "application/x-iroha-query-shard+norito+zstd",
            RowsetCodec = "application/x-iroha-query-shard-rowset+norito",
            Compression = "zstd",
            DefaultPartitionCount = 4096,
            MetadataKeys = metadataKeys,
            ExportSupportedResources = exportSupportedResources,
        };
        var query = new ToriiNodeQueryCapabilities
        {
            Aggregate = aggregate,
            Projection = projection,
        };

        allowedSigning[0] = "mutated";
        allowedCurveIds[0] = 99;
        allowedCurveBitmap[0] = 0;
        supportedResources[0] = "mutated";
        metadataKeys[0] = "mutated";
        exportSupportedResources[0] = "mutated";

        AssertDetachedStringList(() => sm.AllowedSigning, "ed25519", "mutated-getter");
        AssertDetachedIntList(() => curves.AllowedCurveIds, 1, 99);
        AssertDetachedUInt64List(() => curves.AllowedCurveBitmap, 26, 0);
        AssertDetachedStringList(() => aggregate.SupportedResources, "accounts", "mutated-getter");
        AssertDetachedStringList(() => projection.MetadataKeys, "query_projection.locator", "mutated-getter");
        AssertDetachedStringList(() => projection.ExportSupportedResources, "accounts", "mutated-getter");

        static void AssertDetachedStringList(Func<IReadOnlyList<string>> getter, string expectedFirst, string replacementFirst)
        {
            var detached = Assert.IsType<string[]>(getter());
            Assert.Equal(expectedFirst, detached[0]);
            detached[0] = replacementFirst;
            var stored = Assert.IsType<string[]>(getter());
            Assert.NotSame(detached, stored);
            Assert.Equal(expectedFirst, stored[0]);
        }

        static void AssertDetachedIntList(Func<IReadOnlyList<int>> getter, int expectedFirst, int replacementFirst)
        {
            var detached = Assert.IsType<int[]>(getter());
            Assert.Equal(expectedFirst, detached[0]);
            detached[0] = replacementFirst;
            var stored = Assert.IsType<int[]>(getter());
            Assert.NotSame(detached, stored);
            Assert.Equal(expectedFirst, stored[0]);
        }

        static void AssertDetachedUInt64List(Func<IReadOnlyList<ulong>> getter, ulong expectedFirst, ulong replacementFirst)
        {
            var detached = Assert.IsType<ulong[]>(getter());
            Assert.Equal(expectedFirst, detached[0]);
            detached[0] = replacementFirst;
            var stored = Assert.IsType<ulong[]>(getter());
            Assert.NotSame(detached, stored);
            Assert.Equal(expectedFirst, stored[0]);
        }
    }

