    public static IEnumerable<object?[]> InvalidNodeCapabilityResponses()
    {
        foreach (var field in RequiredNodeCapabilityScalarFields())
        {
            yield return new object?[]
            {
                field,
                RemoveNodeCapabilitiesResponseField(field),
                "must not be null",
            };
        }

        foreach (var field in RequiredNodeCapabilityStringFields())
        {
            yield return new object?[]
            {
                field,
                NodeCapabilitiesResponseJson(field, null),
                "must not be null",
            };
            yield return new object?[]
            {
                field,
                RemoveNodeCapabilitiesResponseField(field),
                "must not be null",
            };
        }

        foreach (var field in RequiredNodeCapabilityStringListElementFields())
        {
            yield return new object?[]
            {
                field,
                NodeCapabilitiesResponseJson(field, null),
                "must not be null",
            };
        }

        yield return new object?[] { "abi_version", NodeCapabilitiesResponseJson("abi_version", -1), "non-negative" };
        yield return new object?[] { "abi_version", NodeCapabilitiesResponseJson("abi_version", 0), "must be 1" };
        yield return new object?[] { "abi_version", NodeCapabilitiesResponseJson("abi_version", 2), "must be 1" };
        yield return new object?[]
        {
            "data_model_version",
            NodeCapabilitiesResponseJson("data_model_version", -1),
            "non-negative",
        };
        yield return new object?[]
        {
            "signed_transaction_schema_hash_hex",
            NodeCapabilitiesResponseJson("signed_transaction_schema_hash_hex", " " + SignedTransactionSchemaHashHex),
            "surrounding whitespace",
        };
        yield return new object?[]
        {
            "signed_transaction_schema_hash_hex",
            NodeCapabilitiesResponseJson(
                "signed_transaction_schema_hash_hex",
                SignedTransactionSchemaHashHex.ToUpperInvariant()),
            "lowercase hex",
        };
        yield return new object?[]
        {
            "signed_transaction_schema_hash_hex",
            NodeCapabilitiesResponseJson("signed_transaction_schema_hash_hex", SignedTransactionSchemaHashHex[..31]),
            "32-character",
        };
        yield return new object?[]
        {
            "signed_transaction_schema_hash_hex",
            NodeCapabilitiesResponseJson("signed_transaction_schema_hash_hex", SignedTransactionSchemaHashHex[..31] + "z"),
            "lowercase hex",
        };
        yield return new object?[] { "crypto", NodeCapabilitiesResponseJson("crypto", null), "must not be null" };
        yield return new object?[] { "crypto.sm", NodeCapabilitiesResponseJson("crypto.sm", null), "must not be null" };
        yield return new object?[]
        {
            "crypto.sm.default_hash",
            NodeCapabilitiesResponseJson("crypto.sm.default_hash", ""),
            "non-empty",
        };
        yield return new object?[]
        {
            "crypto.sm.default_hash",
            NodeCapabilitiesResponseJson("crypto.sm.default_hash", " blake2b-256"),
            "surrounding whitespace",
        };
        yield return new object?[]
        {
            "crypto.sm.default_hash",
            NodeCapabilitiesResponseJson("crypto.sm.default_hash", "blake2b 256"),
            "whitespace",
        };
        yield return new object?[]
        {
            "crypto.sm.allowed_signing",
            NodeCapabilitiesResponseJson("crypto.sm.allowed_signing", null),
            "must not be null",
        };
        yield return new object?[]
        {
            "crypto.sm.allowed_signing",
            NodeCapabilitiesResponseJson("crypto.sm.allowed_signing", new JsonArray()),
            "must include ed25519",
        };
        yield return new object?[]
        {
            "crypto.sm.allowed_signing[0]",
            NodeCapabilitiesResponseJson("crypto.sm.allowed_signing[0]", ""),
