    [Fact]
    public void AccountQueryResponseListsSnapshotInitAndAccessValues()
    {
        static void AssertSnapshot<T>(List<T> source, Func<IReadOnlyList<T>> getItems, T original, T replacement)
            where T : class
        {
            source.Add(replacement);
            var firstAccess = Assert.IsType<T[]>(getItems());
            Assert.Same(original, Assert.Single(firstAccess));
            firstAccess[0] = replacement;
            var secondAccess = Assert.IsType<T[]>(getItems());
            Assert.Same(original, Assert.Single(secondAccess));
        }

        var aliasItem = new ToriiAccountAliasLookupItem
        {
            Alias = "merchant@paynet.universal",
            Dataspace = "universal",
            Domain = "paynet",
            IsPrimary = true,
        };
        var replacementAliasItem = aliasItem with { Alias = "backup@paynet.universal", IsPrimary = false };
        var aliasItems = new List<ToriiAccountAliasLookupItem> { aliasItem };
        var aliasResponse = new ToriiAccountAliasLookupResponse
        {
            AccountId = AliasLookupAccountId,
            Items = aliasItems,
            Total = 1,
            Source = "on_chain",
        };

        AssertSnapshot(aliasItems, () => aliasResponse.Items, aliasItem, replacementAliasItem);
        var aliasJson = JsonSerializer.Serialize(aliasResponse);
        var roundTripAliases = Assert.IsType<ToriiAccountAliasLookupResponse>(
            JsonSerializer.Deserialize<ToriiAccountAliasLookupResponse>(aliasJson));
        Assert.Equal("merchant@paynet.universal", Assert.Single(roundTripAliases.Items).Alias);

        var permission = new ToriiAccountPermission
        {
            Name = "CanResolveAccountAlias",
            Payload = JsonNode.Parse("""{"dataspace":7}"""),
        };
        var replacementPermission = permission with { Name = "CanRegisterAccountAlias" };
        var permissionItems = new List<ToriiAccountPermission> { permission };
        var permissionsPage = new Page<ToriiAccountPermission>(permissionItems.ToImmutableArray(), null, 1);

        permissionItems[0] = replacementPermission;
        Assert.Equal(permission, permissionsPage.Items[0]);
        var permissionsJson = AccountPermissionsResponseJson("total", 1);
        var roundTripPermissions = ReadPermissionPage(permissionsJson);
