    public static IEnumerable<object?[]> InvalidExplorerDirectoryResponses()
    {
        yield return new object?[]
        {
            "accounts-page",
            "items",
            ExplorerDirectoryResponseJson("accounts-page", "items", null),
            "must not be null",
        };
        yield return new object?[]
        {
            "accounts-page",
            "items[0]",
            ExplorerDirectoryResponseJson("accounts-page", "items[0]", null),
            "must not be null",
        };
        yield return new object?[]
        {
            "accounts-page",
            "items[0].id",
            ExplorerDirectoryResponseJson("accounts-page", "items[0].id", " sorauﾛ1PﾉｳﾇmEｴWｵebHﾑ6ﾔﾙｲヰiwuCWErJ7uｽoPGｱﾔnjﾑKﾋTCW2PV"),
            "surrounding whitespace",
        };
        foreach (var invalidAccountId in InvalidCanonicalAccountIds())
        {
            yield return new object?[]
            {
                "accounts-page",
                "items[0].id",
                ExplorerDirectoryResponseJson("accounts-page", "items[0].id", invalidAccountId),
                "canonical I105",
            };
            yield return new object?[]
            {
                "account-detail",
                "i105_address",
                ExplorerDirectoryResponseJson("account-detail", "i105_address", invalidAccountId),
                "canonical I105",
            };
        }
        yield return new object?[]
        {
            "account-detail",
            "i105_address",
            ExplorerDirectoryResponseJson("account-detail", "i105_address", "i105:sorauロ 1Nholder"),
            "whitespace",
        };
        yield return new object?[]
        {
            "domains-page",
            "items",
            ExplorerDirectoryResponseJson("domains-page", "items", null),
            "must not be null",
        };
        yield return new object?[]
        {
            "domains-page",
            "items[0]",
            ExplorerDirectoryResponseJson("domains-page", "items[0]", null),
            "must not be null",
        };
        yield return new object?[]
        {
            "domains-page",
            "items[0].id",
            ExplorerDirectoryResponseJson("domains-page", "items[0].id", "wonderland paynet"),
            "whitespace",
        };
        yield return new object?[]
        {
            "domains-page",
            "items[0].logo",
            ExplorerDirectoryResponseJson("domains-page", "items[0].logo", ""),
            "non-empty",
        };
        yield return new object?[]
        {
            "domain-detail",
            "owned_by",
            ExplorerDirectoryResponseJson("domain-detail", "owned_by", "sorauﾛ1PﾉｳﾇmEｴWｵebHﾑ6ﾔﾙｲヰiwuCWErJ7uｽoPGｱﾔnjﾑKﾋTCW2PV\u0001"),
            "control characters",
        };
        foreach (var invalidAccountId in InvalidCanonicalAccountIds())
        {
            yield return new object?[]
            {
                "domains-page",
                "items[0].owned_by",
                ExplorerDirectoryResponseJson("domains-page", "items[0].owned_by", invalidAccountId),
                "canonical I105",
            };
            yield return new object?[]
            {
                "domain-detail",
                "owned_by",
                ExplorerDirectoryResponseJson("domain-detail", "owned_by", invalidAccountId),
                "canonical I105",
            };
        }
    }

