    [Fact]
    public void VpnNetworkRouteListsSnapshotInitAndAccessValues()
    {
        string[] supportedExitClasses = ["standard"];
        string[] profileRoutePushes = ["10.0.0.0/8"];
        string[] profileExcludedRoutes = ["127.0.0.0/8"];
        string[] profileDnsServers = ["1.1.1.1"];
        string[] profileTunnelAddresses = ["10.208.0.2/32"];
        var profile = new ToriiVpnProfile
        {
            SupportedExitClasses = supportedExitClasses,
            RoutePushes = profileRoutePushes,
            ExcludedRoutes = profileExcludedRoutes,
            DnsServers = profileDnsServers,
            TunnelAddresses = profileTunnelAddresses,
        };

        string[] quoteRoutePushes = ["10.0.0.0/8"];
        string[] quoteExcludedRoutes = ["127.0.0.0/8"];
        string[] quoteDnsServers = ["1.1.1.1"];
        string[] quoteTunnelAddresses = ["10.208.0.2/32"];
        var quote = new ToriiVpnQuote
        {
            RoutePushes = quoteRoutePushes,
            ExcludedRoutes = quoteExcludedRoutes,
            DnsServers = quoteDnsServers,
            TunnelAddresses = quoteTunnelAddresses,
        };

        string[] sessionRoutePushes = ["10.0.0.0/8"];
        string[] sessionExcludedRoutes = ["127.0.0.0/8"];
        string[] sessionDnsServers = ["1.1.1.1"];
        string[] sessionTunnelAddresses = ["10.208.0.2/32"];
        var session = new ToriiVpnSession
        {
            RoutePushes = sessionRoutePushes,
            ExcludedRoutes = sessionExcludedRoutes,
            DnsServers = sessionDnsServers,
            TunnelAddresses = sessionTunnelAddresses,
        };

        supportedExitClasses[0] = "mutated";
        profileRoutePushes[0] = "mutated";
        profileExcludedRoutes[0] = "mutated";
        profileDnsServers[0] = "mutated";
        profileTunnelAddresses[0] = "mutated";
        quoteRoutePushes[0] = "mutated";
        quoteExcludedRoutes[0] = "mutated";
        quoteDnsServers[0] = "mutated";
        quoteTunnelAddresses[0] = "mutated";
        sessionRoutePushes[0] = "mutated";
        sessionExcludedRoutes[0] = "mutated";
        sessionDnsServers[0] = "mutated";
        sessionTunnelAddresses[0] = "mutated";

        AssertDetachedStringList(() => profile.SupportedExitClasses, "standard");
        AssertDetachedStringList(() => profile.RoutePushes, "10.0.0.0/8");
        AssertDetachedStringList(() => profile.ExcludedRoutes, "127.0.0.0/8");
        AssertDetachedStringList(() => profile.DnsServers, "1.1.1.1");
        AssertDetachedStringList(() => profile.TunnelAddresses, "10.208.0.2/32");
        AssertDetachedStringList(() => quote.RoutePushes, "10.0.0.0/8");
        AssertDetachedStringList(() => quote.ExcludedRoutes, "127.0.0.0/8");
        AssertDetachedStringList(() => quote.DnsServers, "1.1.1.1");
        AssertDetachedStringList(() => quote.TunnelAddresses, "10.208.0.2/32");
        AssertDetachedStringList(() => session.RoutePushes, "10.0.0.0/8");
        AssertDetachedStringList(() => session.ExcludedRoutes, "127.0.0.0/8");
        AssertDetachedStringList(() => session.DnsServers, "1.1.1.1");
        AssertDetachedStringList(() => session.TunnelAddresses, "10.208.0.2/32");

        var nullProfileRouteError = Assert.Throws<ArgumentException>(() => new ToriiVpnProfile
        {
            RoutePushes = ["10.0.0.0/8", null!],
        });
        Assert.Equal("RoutePushes[1]", nullProfileRouteError.ParamName);
        Assert.Contains("must not be null", nullProfileRouteError.Message);

        var nullQuoteDnsError = Assert.Throws<ArgumentException>(() => new ToriiVpnQuote
        {
            DnsServers = [null!],
        });
        Assert.Equal("DnsServers[0]", nullQuoteDnsError.ParamName);
        Assert.Contains("must not be null", nullQuoteDnsError.Message);

        static void AssertDetachedStringList(Func<IReadOnlyList<string>?> getter, string expected)
        {
            var returned = Assert.IsType<string[]>(getter());
            returned[0] = "mutated";

            Assert.Equal([expected], getter());
            Assert.NotSame(returned, getter());
        }
    }

    [Fact]
    public void VpnReceiptListSnapshotsInitAndAccessValues()
    {
        var receipt = ValidVpnReceipt();
        ToriiVpnReceipt[] receiptItems = [receipt];
        var receiptList = new ToriiVpnReceiptListResponse
        {
            Items = receiptItems,
            Total = 1,
        };

        receiptItems[0] = ValidVpnReceipt() with { SessionId = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa" };

        AssertDetachedObjectList(
            () => receiptList.Items,
            receipt,
            ValidVpnReceipt() with { SessionId = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa" });

        var nullReceiptItemError = Assert.Throws<ArgumentException>(() => new ToriiVpnReceiptListResponse
        {
            Items = [receipt, null!],
        });
        Assert.Equal("Items[1]", nullReceiptItemError.ParamName);
        Assert.Contains("must not be null", nullReceiptItemError.Message);

        static void AssertDetachedObjectList<T>(Func<IReadOnlyList<T>> getter, T expectedFirst, T replacementFirst)
            where T : class
        {
            var detached = Assert.IsType<T[]>(getter());
            Assert.Same(expectedFirst, detached[0]);
            detached[0] = replacementFirst;
            var stored = Assert.IsType<T[]>(getter());
            Assert.NotSame(detached, stored);
            Assert.Same(expectedFirst, stored[0]);
        }
    }

