                      "relay_tls_spki_sha256_hex": "{{VpnSpkiSha256Hex}}",
                      "relay_certificate_sha256_hex": "{{VpnRelayCertificateSha256Hex}}",
                      "directory_snapshot_digest_hex": "{{VpnDirectorySnapshotDigestHex}}",
                      "route_pushes": [],
                      "excluded_routes": [],
                      "dns_servers": [],
                      "tunnel_addresses": [],
                      "mtu_bytes": 1280,
                      "helper_ticket_hex": "{{VpnHelperTicketHex}}",
                      "bytes_in": 0,
                      "bytes_out": 0,
                      "status": "active"
                    }
                    """),
            };
        });

        using var client = CreateSignedVpnClient(handler);
        var missing = await client.GetVpnSessionAsync(missingSessionId, cancellationToken: TestContext.Current.CancellationToken);
        var active = await client.GetVpnSessionAsync(sessionId, cancellationToken: TestContext.Current.CancellationToken);

        Assert.Null(missing);
        Assert.NotNull(active);
        Assert.Equal(sessionId, active.SessionId);
        Assert.Equal(VpnAccountId, active.AccountId);
        Assert.Equal(quoteId, active.QuoteId);
        Assert.Equal(VpnRelayMldsa65PublicKeyHex, active.RelayMldsa65PublicKeyHex);
    }

