    [Fact]
    public void RawSoraFsChunkerHandleDefaultsOptionalMultihashCodeAndWritesCanonicalPayload()
    {
        var response = JsonSerializer.Deserialize<ToriiSoraFsChunkerHandle>("""
            {
              "profile_id": 1,
              "namespace": "sorafs",
              "name": "sf1",
              "semver": "1.0.0"
            }
            """);

        Assert.NotNull(response);
        Assert.Equal((uint)0, response.MultihashCode);
        Assert.Equal(
            """{"profile_id":1,"namespace":"sorafs","name":"sf1","semver":"1.0.0","multihash_code":0}""",
            JsonSerializer.Serialize(response));
    }

