    [Fact]
    public async Task SubmitSignedQueryAsyncPostsVersionedNoritoPayload()
    {
        var queryBytes = new byte[] { 1, 2, 3, 4, 5 };

        using var handler = new RecordingHandler(request =>
        {
            Assert.Equal(HttpMethod.Post, request.Method);
            Assert.Equal("/v1/query", request.RequestUri!.AbsolutePath);
            Assert.Equal("limit=1", request.RequestUri.Query.TrimStart('?'));
            Assert.Equal("application/x-norito", request.Content!.Headers.ContentType!.MediaType);
            Assert.Equal("application/json", Assert.Single(request.Headers.Accept).MediaType);

            using var stream = request.Content.ReadAsStream();
            using var buffer = new MemoryStream();
            stream.CopyTo(buffer);
            Assert.Equal(queryBytes, buffer.ToArray());

            return new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("""
                    {
                      "kind": "Singular",
                      "value": {
                        "id": "sorauﾛ1NｱｻｸYSafﾇｷヰc5ﾇﾄVxﾏ9jLZヱﾋzsKqurﾊﾘ9ｸ3eｴAｶD54TDT"
                      }
                    }
                    """),
            };
        });

        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler),
            options: null,
            TransactionSubmissionTransportAssurance.OneShotWithoutRedirectsOrRetries);
        using var response = await client.SubmitSignedQueryAsync(queryBytes, query: "limit=1", cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal("Singular", response.RootElement.GetProperty("kind").GetString());
        Assert.Equal("sorauﾛ1NｱｻｸYSafﾇｷヰc5ﾇﾄVxﾏ9jLZヱﾋzsKqurﾊﾘ9ｸ3eｴAｶD54TDT", response.RootElement.GetProperty("value").GetProperty("id").GetString());
    }

