    public static IEnumerable<object?[]> InvalidUaidRouteReadLiterals()
    {
        const string uaidHex = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
        var invalidValues = new (string? Value, string ExpectedMessage)[]
        {
            (null, "non-empty string"),
            ("", "non-empty string"),
            (uaidHex, "canonical"),
            ($"UAID:{uaidHex}", "canonical"),
            ($"uaid:{uaidHex.ToUpperInvariant()}", "canonical"),
            ($" {uaidHex}", "whitespace"),
            ($"{uaidHex} ", "whitespace"),
            ($"uaid: {uaidHex}", "canonical"),
            ($"uaid:{uaidHex}\u0001", "control characters"),
        };

        foreach (var operation in new[] { "portfolio", "bindings", "manifests" })
        {
            foreach (var (value, expectedMessage) in invalidValues)
            {
                yield return new object?[] { operation, value, expectedMessage };
            }
        }
    }

