    [Fact]
    public void FaucetPowVerifyRejectsNonExactNonceBeforeDigest()
    {
        var puzzle = DeterministicFaucetPuzzle(difficultyBits: 1);

        AssertRejectsFaucetPowInput(
            () => ToriiAccountFaucetPow.Verify(CanonicalAccountId, puzzle, " 00", out _),
            "nonceHex",
            "whitespace");
        AssertRejectsFaucetPowInput(
            () => ToriiAccountFaucetPow.Verify(CanonicalAccountId, puzzle, "00\u0001", out _),
            "nonceHex",
            "control characters");
        AssertRejectsFaucetPowInput(
            () => ToriiAccountFaucetPow.Verify(CanonicalAccountId, puzzle, "0", out _),
            "nonceHex",
            "even number of hexadecimal characters");
        AssertRejectsFaucetPowInput(
            () => ToriiAccountFaucetPow.Verify(CanonicalAccountId, puzzle, "gg", out _),
            "nonceHex",
            "even number of hexadecimal characters");
    }

    [Fact]
    public void FaucetPowSolveFindsExpectedNonceForDeterministicPuzzle()
    {
        var solution = ToriiAccountFaucetPow.Solve(
            CanonicalAccountId,
            DeterministicFaucetPuzzle(difficultyBits: 8),
            new ToriiAccountFaucetSolveOptions
            {
                MaxAttempts = 200,
            }, cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal("000000000000008f", solution.NonceHex);
        Assert.Equal("00131aaf07fbd1946655b49ba9ec69c43e153c60ffab73b49b8f04de4de02694", solution.DigestHex);
        Assert.Equal(11, solution.LeadingZeroBits);
        Assert.Equal(144, solution.Attempts);
    }

    [Fact]
    public void FaucetPowSolveRejectsNonExactAlgorithmAndAccountIdBeforeWork()
    {
        AssertRejectsFaucetPowInput(
            () => ToriiAccountFaucetPow.Solve(CanonicalAccountId, DeterministicFaucetPuzzleWithPrivateAlgorithm(
                difficultyBits: 1,
                algorithm: " " + ToriiAccountFaucetPow.Algorithm)),
            "puzzle.Algorithm",
            "whitespace");
        AssertRejectsFaucetPowInput(
            () => ToriiAccountFaucetPow.Solve(CanonicalAccountId, DeterministicFaucetPuzzleWithPrivateAlgorithm(
                difficultyBits: 1,
                algorithm: ToriiAccountFaucetPow.Algorithm + "\u0001")),
            "puzzle.Algorithm",
            "control characters");
        Assert.Throws<NotSupportedException>(() => ToriiAccountFaucetPow.Solve(
            CanonicalAccountId,
            DeterministicFaucetPuzzleWithPrivateAlgorithm(difficultyBits: 1, algorithm: "scrypt-leading-zero-bits-v2"),
            cancellationToken: TestContext.Current.CancellationToken));
        AssertRejectsFaucetPowInput(
            () => ToriiAccountFaucetPow.Solve(" " + CanonicalAccountId, DeterministicFaucetPuzzle(
                difficultyBits: 1)),
            "accountId",
            "whitespace");
        AssertRejectsFaucetPowInput(
            () => ToriiAccountFaucetPow.Solve("merchant@sora", DeterministicFaucetPuzzle(
                difficultyBits: 1)),
            "accountId",
            "canonical I105");
    }

