    private static ToriiAccountFaucetPuzzle DeterministicFaucetPuzzle(
        byte difficultyBits,
        string algorithm = ToriiAccountFaucetPow.Algorithm)
    {
        return new ToriiAccountFaucetPuzzle
        {
            Algorithm = algorithm,
            NetworkId = OnboardingFixtureNetworkId,
            ChainDiscriminant = AccountAddress.DefaultChainDiscriminant,
            DifficultyBits = difficultyBits,
            AnchorHeight = 68,
            AnchorBlockHashHex = "d5c0016a6345e8ea379da42aab1fdc16ba82756e19e0b63c48c14735e8caf7ef",
            ScryptLogN = 4,
            ScryptR = 1,
            ScryptP = 1,
            MaxAnchorAgeBlocks = 6,
        };
    }

    private static ToriiAccountFaucetPuzzle DeterministicFaucetPuzzleWithPrivateAlgorithm(
        byte difficultyBits,
        string algorithm)
    {
        var puzzle = DeterministicFaucetPuzzle(difficultyBits);
        SetPrivateField(puzzle, "algorithm", algorithm);
        return puzzle;
    }

