    public static IEnumerable<object?[]> InvalidAliasResolveOperations()
    {
        var operations = new (string Operation, string ParamName)[]
        {
            ("account", "alias"),
            ("asset", "alias"),
            ("contract", "contractAlias"),
        };
        var invalidValues = new (string? Value, string ExpectedMessage)[]
        {
            (null, "null or whitespace"),
            ("", "null or whitespace"),
            (" merchant@paynet.universal", "whitespace"),
            ("merchant@paynet.universal ", "whitespace"),
            ("merchant @paynet.universal", "whitespace"),
            ("merchant@paynet.universal\u0001", "control characters"),
        };

        foreach (var (operation, paramName) in operations)
        {
            foreach (var (value, expectedMessage) in invalidValues)
            {
                yield return new object?[] { operation, value, paramName, expectedMessage };
            }
        }
    }

