    [InlineData("signing_message_b64", "bWVzc2FnZQ==\u0001", "control characters")]
    [InlineData("signing_message_b64", "not-base64", "valid base64")]
    [InlineData("signing_message_b64", "AR==", "canonical base64")]
    public async Task CallContractAsyncRejectsNonExactSigningMaterialResponse(
        string responseField,
        string responseValue,
        string expectedReason)
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent(ContractCallRawResponseJson(responseField, responseValue)),
        });

        using var client = BoundContractToriiClient(handler);
        var error = await Assert.ThrowsAsync<JsonException>(() =>
            client.CallContractAsync(new ToriiContractCallRequest
            {
                Authority = ContractCallAuthorityAccountId,
                ContractAlias = "router::dex.universal",
                Payload = JsonNode.Parse("""{ "amount": "1" }"""),
                FeePayment = FeePaymentIntent.Authority(Array.Empty<FeeChargeLimit>(), 500_000),
            }, cancellationToken: TestContext.Current.CancellationToken));

        Assert.Contains($"contract call response.{responseField}", error.Message);
        Assert.Contains(expectedReason, error.Message);
        Assert.Equal("/v1/contracts/call", handler.LastRequest!.RequestUri!.AbsolutePath);
    }

