    [Theory]
    [MemberData(nameof(InvalidRuntimeMetadataResponses))]
    public async Task RuntimeMetadataEndpointsRejectMalformedResponses(
        string operation,
        string expectedPath,
        string expectedField,
        string json,
        string expectedMessage)
    {
        using var handler = new RecordingHandler(_ => JsonResponse(json));
        using var client = CreateRuntimeAuthenticatedClient(handler);

        var error = await Assert.ThrowsAsync<JsonException>(async () =>
        {
            switch (operation)
            {
                case "runtime-abi-active":
                    _ = await client.GetRuntimeAbiActiveAsync(cancellationToken: TestContext.Current.CancellationToken);
                    break;
                case "runtime-metrics":
                    _ = await client.GetRuntimeMetricsAsync(cancellationToken: TestContext.Current.CancellationToken);
                    break;
                case "runtime-abi-hash":
                    _ = await client.GetRuntimeAbiHashAsync(cancellationToken: TestContext.Current.CancellationToken);
                    break;
                default:
                    throw new ArgumentOutOfRangeException(
                        nameof(operation),
                        operation,
                        "Unknown runtime metadata operation.");
            }
        });

        Assert.Contains(expectedField, error.Message);
        Assert.Contains(expectedMessage, error.Message);
        Assert.Equal(expectedPath, handler.LastRequest!.RequestUri!.AbsolutePath);
    }

