        yield return new object?[] { "runtime-abi-active", "abi_version", RuntimeMetadataResponseJson("runtime-abi-active", "abi_version", 2), "must be 1" };

        yield return new object?[] { "runtime-metrics", "runtime metrics", "null", "must not be null" };
        yield return new object?[] { "runtime-metrics", "abi_version", RuntimeMetadataResponseJsonWithoutField("runtime-metrics", "abi_version"), "must not be null" };
        yield return new object?[] { "runtime-metrics", "abi_version", RuntimeMetadataResponseJson("runtime-metrics", "abi_version", 0), "must be 1" };
        yield return new object?[] { "runtime-metrics", "upgrade_events_total", RuntimeMetadataResponseJsonWithoutField("runtime-metrics", "upgrade_events_total"), "must not be null" };
        yield return new object?[] { "runtime-metrics", "upgrade_events_total", RuntimeMetadataResponseJson("runtime-metrics", "upgrade_events_total", null), "must not be null" };
        yield return new object?[] { "runtime-metrics", "upgrade_events_total", RuntimeMetadataResponseJson("runtime-metrics", "upgrade_events_total", "bad"), "object" };
        yield return new object?[]
        {
            "runtime-metrics",
            "runtime metrics.upgrade_events_total.proposed",
            """{"abi_version":1,"upgrade_events_total":{"activated":0,"canceled":0}}""",
            "must not be null",
        };
        yield return new object?[]
        {
            "runtime-metrics",
            "runtime metrics.upgrade_events_total.activated",
            """{"abi_version":1,"upgrade_events_total":{"proposed":0,"canceled":0}}""",
            "must not be null",
        };
        yield return new object?[]
        {
            "runtime-metrics",
            "runtime metrics.upgrade_events_total.canceled",
            """{"abi_version":1,"upgrade_events_total":{"proposed":0,"activated":0}}""",
            "must not be null",
        };
        yield return new object?[]
        {
            "runtime-metrics",
            "runtime metrics.upgrade_events_total.proposed",
            """{"abi_version":1,"upgrade_events_total":{"proposed":2,"proposed":3,"activated":1,"canceled":0}}""",
            "must not appear more than once",
        };
        yield return new object?[] { "runtime-metrics", "upgrade_events_total.proposed", RuntimeMetadataResponseJson("runtime-metrics", "upgrade_events_total.proposed", -1L), "non-negative" };
        yield return new object?[] { "runtime-metrics", "upgrade_events_total", RuntimeMetadataResponseJson("runtime-metrics", "upgrade_events_total.canceled", 2L), "activated plus canceled" };

        yield return new object?[] { "runtime-abi-hash", "runtime ABI hash", "null", "must not be null" };
        yield return new object?[] { "runtime-abi-hash", "policy", RuntimeMetadataResponseJsonWithoutField("runtime-abi-hash", "policy"), "must not be null" };
        yield return new object?[] { "runtime-abi-hash", "policy", RuntimeMetadataResponseJson("runtime-abi-hash", "policy", null), "must not be null" };
        yield return new object?[] { "runtime-abi-hash", "policy", RuntimeMetadataResponseJson("runtime-abi-hash", "policy", " V1"), "surrounding whitespace" };
        yield return new object?[] { "runtime-abi-hash", "policy", RuntimeMetadataResponseJson("runtime-abi-hash", "policy", "V 1"), "whitespace" };
        yield return new object?[] { "runtime-abi-hash", "policy", RuntimeMetadataResponseJson("runtime-abi-hash", "policy", "V1\u0001"), "control characters" };
        yield return new object?[] { "runtime-abi-hash", "policy", RuntimeMetadataResponseJson("runtime-abi-hash", "policy", "V2"), "must be V1" };
        yield return new object?[] { "runtime-abi-hash", "abi_hash_hex", RuntimeMetadataResponseJsonWithoutField("runtime-abi-hash", "abi_hash_hex"), "must not be null" };
        yield return new object?[] { "runtime-abi-hash", "abi_hash_hex", RuntimeMetadataResponseJson("runtime-abi-hash", "abi_hash_hex", null), "must not be null" };
        yield return new object?[] { "runtime-abi-hash", "abi_hash_hex", RuntimeMetadataResponseJson("runtime-abi-hash", "abi_hash_hex", "0x" + ContractAbiHashHex), "lowercase 32-byte hex string" };
        yield return new object?[] { "runtime-abi-hash", "abi_hash_hex", RuntimeMetadataResponseJson("runtime-abi-hash", "abi_hash_hex", ContractAbiHashHex.ToUpperInvariant()), "lowercase 32-byte hex string" };
    }

