    [Fact]
    public async Task SendAsyncThrowsToriiApiExceptionWithStatusBodyAndUri()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.UnprocessableEntity)
        {
            Content = new StringContent("""{ "error": "invalid account id literal" }"""),
        });

        using var client = CreateRuntimeAuthenticatedClient(handler);

        var exception = await Assert.ThrowsAsync<ToriiApiException>(() => client.GetNodeCapabilitiesAsync(cancellationToken: TestContext.Current.CancellationToken));

        Assert.Equal(HttpStatusCode.UnprocessableEntity, exception.StatusCode);
        Assert.Equal("https://torii.example/v1/node/capabilities", exception.RequestUri?.ToString());
        Assert.Contains("invalid account id literal", exception.ResponseBody);
    }

    [Fact]
    public async Task SendAsyncRedactsInvalidUtf8ErrorBodyButPreservesStatus()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.BadGateway)
        {
            Content = new ByteArrayContent([0xff, 0xfe, 0xfd]),
            ReasonPhrase = "upstream failed",
        });

        using var client = CreateRuntimeAuthenticatedClient(handler);

        var exception = await Assert.ThrowsAsync<ToriiApiException>(() => client.GetNodeCapabilitiesAsync(cancellationToken: TestContext.Current.CancellationToken));

        Assert.Equal(HttpStatusCode.BadGateway, exception.StatusCode);
        Assert.Equal("https://torii.example/v1/node/capabilities", exception.RequestUri?.ToString());
        Assert.Equal("<response body is not valid UTF-8>", exception.ResponseBody);
        Assert.Contains("response body is not valid UTF-8", exception.Message, StringComparison.Ordinal);
        Assert.DoesNotContain("\ufffd", exception.Message, StringComparison.Ordinal);
    }

    [Fact]
    public async Task SendAsyncBoundsErrorBodies()
    {
        using var handler = new RecordingHandler(_ => new HttpResponseMessage(HttpStatusCode.BadGateway)
        {
            Content = new ByteArrayContent(new byte[64 * 1024 + 1]),
        });
        using var client = new ToriiClient(
            new Uri("https://torii.example"),
            new HttpClient(handler));

        var exception = await Assert.ThrowsAsync<ToriiApiException>(() =>
            client.GetHealthAsync(TestContext.Current.CancellationToken));

        Assert.Equal(HttpStatusCode.BadGateway, exception.StatusCode);
        Assert.Equal("<response body exceeds the 65536-byte limit>", exception.ResponseBody);
    }

    private static string ArtifactHashLiteral(string codeHash) =>
        JsonSerializer.SerializeToNode(new ContractArtifactId(0, codeHash))!["code_hash"]!.GetValue<string>();

    private static Task InvokeContractCodeReadOperationAsync(
        ToriiClient client,
        string operation,
        string? codeHash)
    {
        return operation switch
        {
            "manifest" => client.GetContractCodeAsync(new ContractArtifactId(0, codeHash!)),
            "bytes" => client.GetContractCodeBytesResponseAsync(new ContractArtifactId(0, codeHash!)),
            "view" => client.GetContractCodeViewAsync(new ContractArtifactId(0, codeHash!)),
            "verified-source-job" => client.GetContractVerifiedSourceJobAsync(new ContractArtifactId(0, codeHash!), "job-1"),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown contract code read operation."),
        };
    }

    private static Task InvokeContractMetadataHashResponseOperationAsync(
        ToriiClient client,
        string operation)
    {
        return operation switch
        {
            "contract-code" => client.GetContractCodeAsync(new ContractArtifactId(0, ContractCodeHashHex)),
            "contract-code-view" => client.GetContractCodeViewAsync(new ContractArtifactId(0, ContractCodeHashHex)),
            "explorer-instruction-contract-view" => client.GetExplorerInstructionContractViewAsync("tx-detail", 2),
            "contract-call" => client.CallContractAsync(ValidContractCallRequest()),
            "contract-view-success" => client.ExecuteContractViewAsync(ValidContractViewRequest()),
            "contract-view-error" => client.ExecuteContractViewAsync(ValidContractViewRequest()),
            "verified-source-submit" => client.SubmitContractVerifiedSourceJobAsync(new ContractArtifactId(0, ContractCodeHashHex),
                ValidContractVerifiedSourceSubmission()),
            "verified-source-get" => client.GetContractVerifiedSourceJobAsync(new ContractArtifactId(0, ContractCodeHashHex), "job-1"),
            "runtime-abi-hash" => client.GetRuntimeAbiHashAsync(),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown contract metadata hash response operation."),
        };
    }

    private static Task InvokeExplorerResponseOperationAsync(
        ToriiClient client,
        string operation)
    {
        return operation switch
        {
            "blocks-page" => client.ExplorerBlocks.GetPageAsync(),
            "block" => client.GetExplorerBlockAsync("0007"),
            "transactions-page" => client.ExplorerTransactions.GetPageAsync(),
            "transactions-latest" => client.ExplorerLatestTransactions.GetPageAsync(),
            "transaction-detail" => client.GetExplorerTransactionAsync("tx-detail"),
            "instructions-page" => client.ExplorerInstructions.GetPageAsync(),
            "instructions-latest" => client.ExplorerLatestInstructions.GetPageAsync(),
            "instruction-detail" => client.GetExplorerInstructionAsync("tx-detail", 2),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown explorer response operation."),
        };
    }

    private static Task InvokeExplorerDirectoryResponseOperationAsync(
        ToriiClient client,
        string operation)
    {
        return operation switch
