    private static void DeserializeRawExplorerSsePayload(string operation, string json)
    {
        switch (operation)
        {
            case "blocks":
                _ = JsonSerializer.Deserialize<ToriiExplorerBlock>(json);
                break;
            case "transactions":
                _ = JsonSerializer.Deserialize<ToriiExplorerTransaction>(json);
                break;
            case "instructions":
                _ = JsonSerializer.Deserialize<ToriiExplorerInstruction>(json);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown explorer SSE operation.");
        }
    }

