    private static bool RequiredBoolValue(object? value)
    {
        return value is bool boolean
            ? boolean
            : throw new ArgumentException("Expected a boolean test value.", nameof(value));
    }

    private static ulong RequiredUInt64Value(object? value)
    {
        return value is ulong number
            ? number
            : throw new ArgumentException("Expected an unsigned integer test value.", nameof(value));
    }

    private static uint RequiredUInt32Value(object? value)
    {
        return value is uint number
            ? number
            : throw new ArgumentException("Expected an unsigned integer test value.", nameof(value));
    }

    private static byte RequiredByteValue(object? value)
    {
        return value is byte number
            ? number
            : throw new ArgumentException("Expected an unsigned 8-bit integer test value.", nameof(value));
    }

    private static int RequiredInt32Value(object? value)
    {
        return value is int number
            ? number
            : throw new ArgumentException("Expected an integer test value.", nameof(value));
    }

    private static long RequiredInt64Value(object? value)
    {
        return value is long number
            ? number
            : throw new ArgumentException("Expected an integer test value.", nameof(value));
    }

    private static double RequiredDoubleValue(object? value)
    {
        return value is double number
            ? number
            : throw new ArgumentException("Expected a double test value.", nameof(value));
    }

    private static void SetPrivateField(object target, string fieldName, object? value)
    {
        var field = target.GetType().GetField(
            fieldName,
            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
        Assert.NotNull(field);
        field.SetValue(target, value);
    }

    private static void DeserializeRawExplorerPage(string operation, string json)
    {
        switch (operation)
        {
            case "blocks-page":
                _ = ReadExplorerPage<ToriiExplorerBlock>(json);
                break;
            case "transactions-page":
                _ = ReadExplorerPage<ToriiExplorerTransaction>(json);
                break;
            case "transactions-latest":
                _ = ReadExplorerPage<ToriiExplorerTransaction>(json);
                break;
            case "transaction-detail":
                _ = JsonSerializer.Deserialize<ToriiExplorerTransactionDetail>(json);
                break;
            case "instructions-page":
                _ = ReadExplorerPage<ToriiExplorerInstruction>(json);
                break;
            case "instructions-latest":
                _ = ReadExplorerPage<ToriiExplorerInstruction>(json);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown explorer page operation.");
        }
    }

