    internal static string TransactionSubmissionCapabilitiesJson(
        int dataModelVersion = ToriiNodeCapabilities.ExpectedDataModelVersion,
        string signedTransactionSchemaHashHex =
            ToriiNodeCapabilities.ExpectedSignedTransactionSchemaHashHex)
    {
        var response = JsonNode.Parse(
            NodeCapabilitiesResponseJson("data_model_version", dataModelVersion))!
            .AsObject();
        response["signed_transaction_schema_hash_hex"] = signedTransactionSchemaHashHex;
        return response.ToJsonString();
    }

    private static string NodeCapabilitiesResponseJsonWithProjectionAvailability(
        bool shardCatalog,
        bool archiveExport,
        JsonArray exportSupportedResources)
    {
        var response = JsonNode.Parse(NodeCapabilitiesResponseJson("query.projection.shard_catalog_v1", shardCatalog))!.AsObject();
        var query = response["query"]!.AsObject();
        var projection = query["projection"]!.AsObject();
        projection["archive_export_v1"] = archiveExport;
        projection["export_supported_resources"] = exportSupportedResources;
        return response.ToJsonString();
    }

    private static string NodeCapabilitiesResponseJsonWithAcceleration(string policy, bool neonSm3, bool neonSm4)
    {
