        var sm = crypto["sm"]!.AsObject();
        var acceleration = sm["acceleration"]!.AsObject();
        acceleration["neon_sm3"] = neonSm3;
        acceleration["neon_sm4"] = neonSm4;
        return response.ToJsonString();
    }

    private static string NodeCapabilitiesResponseJsonWithSm(string defaultHash, JsonArray allowedSigning)
