    private static string RemoveNodeCapabilitiesResponseField(string field)
    {
        var response = JsonNode.Parse(NodeCapabilitiesResponseJson("abi_version", 1))!.AsObject();
        var parts = field.Split('.');
        var node = response;
        for (var index = 0; index < parts.Length - 1; index++)
        {
            node = node[parts[index]]!.AsObject();
        }

        RemoveRequiredJsonField(node, parts[^1]);
        return response.ToJsonString();
    }

    private static string RemoveNodeCapabilitiesPayloadField(string operation, string field)
    {
        var response = JsonNode.Parse(NodeCapabilitiesResponseJson("abi_version", 1))!.AsObject();
        var payload = operation switch
        {
            "capabilities" => response,
            "crypto" => response["crypto"]!.AsObject(),
            "sm" => response["crypto"]!["sm"]!.AsObject(),
            "acceleration" => response["crypto"]!["sm"]!["acceleration"]!.AsObject(),
            "curves" => response["crypto"]!["curves"]!.AsObject(),
            "query" => response["query"]!.AsObject(),
            "aggregate" => response["query"]!["aggregate"]!.AsObject(),
            "projection" => response["query"]!["projection"]!.AsObject(),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown raw node capabilities operation."),
        };

        RemoveRequiredJsonField(payload, field);
        return payload.ToJsonString();
    }

    private static void RemoveRequiredJsonField(JsonObject node, string field)
    {
        if (!node.Remove(field))
        {
            throw new InvalidOperationException($"Fixture is missing {field}.");
        }
    }

    private static object? DeserializeRawNodeCapabilitiesPayload(string operation, string json)
    {
        return operation switch
        {
            "capabilities" => JsonSerializer.Deserialize<ToriiNodeCapabilities>(json),
            "crypto" => JsonSerializer.Deserialize<ToriiNodeCryptoCapabilities>(json),
            "sm" => JsonSerializer.Deserialize<ToriiNodeSmCapabilities>(json),
            "acceleration" => JsonSerializer.Deserialize<ToriiNodeSmAcceleration>(json),
            "curves" => JsonSerializer.Deserialize<ToriiNodeCurveCapabilities>(json),
            "query" => JsonSerializer.Deserialize<ToriiNodeQueryCapabilities>(json),
            "aggregate" => JsonSerializer.Deserialize<ToriiNodeAggregateQueryCapabilities>(json),
            "projection" => JsonSerializer.Deserialize<ToriiNodeProjectionCapabilities>(json),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown raw node capabilities operation."),
        };
    }

    private static string NodeCapabilitiesPayloadJson(string operation, string field, object? value)
    {
        var path = operation switch
        {
            "capabilities" => field,
            "crypto" => $"crypto.{field}",
            "sm" => $"crypto.sm.{field}",
            "acceleration" => $"crypto.sm.acceleration.{field}",
            "curves" => $"crypto.curves.{field}",
            "query" => $"query.{field}",
            "aggregate" => $"query.aggregate.{field}",
            "projection" => $"query.projection.{field}",
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown raw node capabilities operation."),
        };
        var response = JsonNode.Parse(NodeCapabilitiesResponseJson(path, value))!.AsObject();
        return operation switch
        {
            "capabilities" => response.ToJsonString(),
            "crypto" => response["crypto"]!.ToJsonString(),
            "sm" => response["crypto"]!["sm"]!.ToJsonString(),
            "acceleration" => response["crypto"]!["sm"]!["acceleration"]!.ToJsonString(),
            "curves" => response["crypto"]!["curves"]!.ToJsonString(),
            "query" => response["query"]!.ToJsonString(),
            "aggregate" => response["query"]!["aggregate"]!.ToJsonString(),
            "projection" => response["query"]!["projection"]!.ToJsonString(),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown raw node capabilities operation."),
        };
    }

    private static string NodeCapabilitiesDuplicatePropertyJson(string operation, string propertyName)
    {
        var value = propertyName switch
        {
            "abi_version" or "registry_version" => "1",
            "enabled" or "scalar" or "neon_sm3" or "v1" => "true",
            "sm" or "curves" or "aggregate" => "null",
            _ => "\"duplicate\"",
        };

        return $$"""
            {
              "{{propertyName}}": {{value}},
              "{{propertyName}}": {{value}}
            }
            """;
    }

    private static string NodeCapabilitiesUnknownExtensionDuplicateJson(string operation)
    {
        var response = JsonNode.Parse(NodeCapabilitiesResponseJson("abi_version", 1))!.AsObject();
        var node = operation switch
        {
            "capabilities" => response,
            "crypto" => response["crypto"]!.AsObject(),
            "sm" => response["crypto"]!["sm"]!.AsObject(),
            "acceleration" => response["crypto"]!["sm"]!["acceleration"]!.AsObject(),
            "curves" => response["crypto"]!["curves"]!.AsObject(),
            "query" => response["query"]!.AsObject(),
            "aggregate" => response["query"]!["aggregate"]!.AsObject(),
            "projection" => response["query"]!["projection"]!.AsObject(),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown raw node capabilities operation."),
        };
        var json = node.ToJsonString();
        return json.Insert(json.Length - 1, ""","audit":{"nonce":1,"nonce":2}""");
    }

    private static string RuntimeMetadataResponseJson(string operation, string field, object? value)
    {
        var response = RuntimeMetadataResponseObject(operation, out var counters);

        switch (field)
        {
            case "abi_version":
                response["abi_version"] = JsonValueForMetadata(value);
                break;
            case "upgrade_events_total":
                response["upgrade_events_total"] = JsonValueForMetadata(value);
                break;
            case "upgrade_events_total.proposed":
                counters!["proposed"] = JsonValueForMetadata(value);
                break;
            case "upgrade_events_total.activated":
                counters!["activated"] = JsonValueForMetadata(value);
                break;
            case "upgrade_events_total.canceled":
                counters!["canceled"] = JsonValueForMetadata(value);
                break;
            case "policy":
                response["policy"] = JsonValueForMetadata(value);
                break;
            case "abi_hash_hex":
                response["abi_hash_hex"] = JsonValueForMetadata(value);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(field), field, "Unknown runtime metadata field.");
        }

        return response.ToJsonString();
    }

    private static string RuntimeMetadataResponseJsonWithoutField(string operation, string field)
    {
        var response = RuntimeMetadataResponseObject(operation, out var counters);

        switch (field)
        {
            case "abi_version":
                response.Remove("abi_version");
                break;
            case "upgrade_events_total":
                response.Remove("upgrade_events_total");
                break;
            case "upgrade_events_total.proposed":
                counters!.Remove("proposed");
                break;
            case "upgrade_events_total.activated":
                counters!.Remove("activated");
                break;
            case "upgrade_events_total.canceled":
                counters!.Remove("canceled");
                break;
            case "policy":
                response.Remove("policy");
                break;
            case "abi_hash_hex":
                response.Remove("abi_hash_hex");
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(field), field, "Unknown runtime metadata field.");
        }

        return response.ToJsonString();
    }

    private static JsonObject RuntimeMetadataResponseObject(string operation, out JsonObject? counters)
    {
        JsonObject response;
        counters = null;
        switch (operation)
        {
            case "runtime-abi-active":
                response = new JsonObject
                {
                    ["abi_version"] = 1,
                };
                break;
            case "runtime-metrics":
                counters = new JsonObject
                {
                    ["proposed"] = 2,
                    ["activated"] = 1,
                    ["canceled"] = 0,
                };
                response = new JsonObject
                {
                    ["abi_version"] = 1,
                    ["upgrade_events_total"] = counters,
                };
                break;
            case "runtime-abi-hash":
                response = new JsonObject
                {
                    ["policy"] = "V1",
                    ["abi_hash_hex"] = ContractAbiHashHex,
                };
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown runtime metadata operation.");
        }

        return response;
    }

    private static JsonNode? JsonValueForMetadata(object? value)
    {
        return value switch
        {
            null => null,
            JsonNode node => node,
            string text => JsonValue.Create(text),
            bool flag => JsonValue.Create(flag),
            long number => JsonValue.Create(number),
            int number => JsonValue.Create(number),
            _ => throw new ArgumentOutOfRangeException(nameof(value), value, "Unsupported metadata JSON value."),
        };
    }

