    private static string UaidManifestsResponseJson(string field, object? value)
    {
        const string uaid = "uaid:0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
        var accounts = new JsonArray(UaidManifestAccountId);
        var revocation = new JsonObject
        {
            ["epoch"] = 122,
            ["reason"] = "rotated",
        };
        var lifecycle = new JsonObject
        {
            ["activated_epoch"] = 121,
            ["expired_epoch"] = 240,
            ["revocation"] = revocation,
        };
        var manifest = new JsonObject
        {
            ["dataspace_id"] = 42,
            ["dataspace_alias"] = "payments",
            ["manifest_hash"] = UaidManifestHashHex,
            ["status"] = "Revoked",
            ["lifecycle"] = lifecycle,
            ["accounts"] = accounts,
            ["manifest"] = new JsonObject
            {
                ["version"] = 1,
                ["uaid"] = uaid,
                ["dataspace"] = 42,
                ["issued_ms"] = 1710000000000,
                ["activation_epoch"] = 120,
                ["entries"] = new JsonArray(),
            },
        };
        var manifests = new JsonArray(manifest);
        var response = new JsonObject
        {
            ["total"] = 1,
            ["next_cursor"] = null,
            ["items"] = manifests,
        };

        switch (field)
        {
            case "uaid":
                manifest["manifest"]!["uaid"] = JsonValueForUaid(value);
                break;
            case "total":
                response["total"] = JsonValueForUaid(value);
                break;
            case "has_more":
                response["has_more"] = JsonValueForUaid(value);
                break;
            case "count_mode":
                response["count_mode"] = JsonValueForUaid(value);
                break;
            case "items":
                response["items"] = JsonValueForUaid(value);
                break;
            case "items[0]":
                manifests[0] = JsonValueForUaid(value);
                break;
            case "items[0].dataspace_id":
                manifest["dataspace_id"] = JsonValueForUaid(value);
                break;
            case "items[0].dataspace_alias":
                manifest["dataspace_alias"] = JsonValueForUaid(value);
                break;
            case "items[0].manifest_hash":
                manifest["manifest_hash"] = JsonValueForUaid(value);
                break;
            case "items[0].status":
                manifest["status"] = JsonValueForUaid(value);
                break;
            case "items[0].lifecycle":
                manifest["lifecycle"] = JsonValueForUaid(value);
                break;
            case "items[0].lifecycle.activated_epoch":
                lifecycle["activated_epoch"] = JsonValueForUaid(value);
                break;
            case "items[0].lifecycle.expired_epoch":
                lifecycle["expired_epoch"] = JsonValueForUaid(value);
                break;
            case "items[0].lifecycle.revocation":
                lifecycle["revocation"] = JsonValueForUaid(value);
                break;
            case "items[0].lifecycle.revocation.epoch":
                revocation["epoch"] = JsonValueForUaid(value);
                break;
            case "items[0].lifecycle.revocation.reason":
                revocation["reason"] = JsonValueForUaid(value);
                break;
            case "items[0].accounts":
                manifest["accounts"] = JsonValueForUaid(value);
                break;
            case "items[0].accounts[0]":
                accounts[0] = JsonValueForUaid(value);
                break;
            case "items[0].manifest":
                manifest["manifest"] = JsonValueForUaid(value);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(field), field, "Unknown UAID manifests response field.");
        }

        return response.ToJsonString();
    }

    private static JsonNode? JsonValueForUaid(object? value)
    {
        return value switch
        {
            null => null,
            JsonNode node => node,
            string text => JsonValue.Create(text),
            ulong number => JsonValue.Create(number),
            uint number => JsonValue.Create(number),
            long number => JsonValue.Create(number),
            int number => JsonValue.Create(number),
            bool boolean => JsonValue.Create(boolean),
            _ => throw new ArgumentOutOfRangeException(nameof(value), value, "Unsupported UAID JSON value."),
        };
    }

    private static string JsonWithIgnoredAuditDuplicateAfter(string json, string marker, string description)
    {
        var index = json.IndexOf(marker, StringComparison.Ordinal);
        if (index < 0)
        {
            throw new InvalidOperationException($"{description} fixture is missing the expected marker.");
        }

        return json.Insert(index + marker.Length, ",\"audit\":{\"nonce\":1,\"nonce\":2}");
    }

    private static object? DeserializeRawUaidPortfolioPayload(string operation, string json)
    {
        return operation switch
        {
