            "account" => JsonSerializer.Deserialize<ToriiUaidPortfolioAccount>(json),
            "dataspace" => JsonSerializer.Deserialize<ToriiUaidPortfolioDataspace>(json),
            "response" => JsonSerializer.Deserialize<ToriiUaidPortfolioResponse>(json),
