    private static string ExplorerDirectoryDuplicateItemPropertyJson(string operation, string propertyName)
    {
        var item = operation is "accounts-page" or "account-detail"
            ? ExplorerDirectoryAccountJsonObject()
            : ExplorerDirectoryDomainJsonObject();

        item[propertyName] = JsonValueForExplorer("duplicate");
        var itemJson = item.ToJsonString();
        var duplicate = $"\"{propertyName}\": \"duplicate\", \"{propertyName}\": \"duplicate\"";
        var firstProperty = $"\"{propertyName}\":\"duplicate\"";
        itemJson = itemJson.Replace(firstProperty, duplicate, StringComparison.Ordinal);

        if (operation.EndsWith("-page", StringComparison.Ordinal))
        {
            return $$"""{"pagination":{"limit":10,"next_cursor":"bmV4dA","has_more":true},"items":[{{itemJson}}]}""";
        }

        return itemJson;
    }

