    private static string JsonWithIgnoredAuditDuplicate(string json)
    {
        return json.Insert(json.Length - 1, ",\"audit\":{\"nonce\":1,\"nonce\":2}");
    }

    private static string RemoveTopLevelJsonField(string json, string field)
    {
        var response = (JsonObject)JsonNode.Parse(json)!;
        response.Remove(field);
        return response.ToJsonString();
    }

    private static string RemoveNestedJsonField(string json, string objectField, string field)
    {
        var response = (JsonObject)JsonNode.Parse(json)!;
        ((JsonObject)response[objectField]!).Remove(field);
        return response.ToJsonString();
    }

    private static string RemoveFirstArrayItemObjectJsonField(string json, string arrayField, string field)
    {
        var response = (JsonObject)JsonNode.Parse(json)!;
        var items = (JsonArray)response[arrayField]!;
        ((JsonObject)items[0]!).Remove(field);
        return response.ToJsonString();
    }

    private static string JsonWithFirstItemIgnoredAuditDuplicate(string json)
    {
        const string marker = "}],\"total\"";
        var index = json.IndexOf(marker, StringComparison.Ordinal);
        if (index < 0)
        {
            throw new InvalidOperationException("Page fixture is missing the first item boundary.");
        }

        return json.Insert(index, ",\"audit\":{\"nonce\":1,\"nonce\":2}");
    }

