                response["storage_class"] = JsonValueForSoraFs(value);
                break;
            case "Storage_Class":
                response.Remove("storage_class");
                response["Storage_Class"] = JsonValueForSoraFs(value);
                break;
            case "storage_class.type":
                storageClass["type"] = JsonValueForSoraFs(value);
                break;
            case "retention_epoch":
                response["retention_epoch"] = JsonValueForSoraFs(value);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(field), field, "Unknown SoraFS pin policy field.");
        }

        return response.ToJsonString();
    }

