    private static string ContractCallViewResponseJson(string operation, string field, object? value)
    {
        var response = operation switch
        {
            "contract-call" => ContractCallResponseJsonObject(),
            "contract-view-success" => ContractViewSuccessResponseJsonObject(),
            "contract-view-error" => ContractViewErrorResponseJsonObject(includeVmDiagnostic: true),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown contract call/view operation."),
        };

        switch (field)
        {
            case "dataspace":
            case "contract_id":
            case "contract_address":
            case "code_hash_hex":
            case "abi_hash_hex":
            case "entrypoint":
            case "error":
            case "vm_diagnostic":
                response[field] = JsonValueForContractCallView(value);
                break;
            case "vm_diagnostic.trap_kind":
            case "vm_diagnostic.message":
            case "vm_diagnostic.function":
            case "vm_diagnostic.source_path":
            case "vm_diagnostic.current_function":
            case "vm_diagnostic.gas_limit":
            case "vm_diagnostic.gas_remaining":
            case "vm_diagnostic.gas_used":
            case "vm_diagnostic.max_cycles":
            case "vm_diagnostic.cycles":
            case "vm_diagnostic.stack_limit_bytes":
            case "vm_diagnostic.stack_bytes_used":
                var diagnostic = (JsonObject)response["vm_diagnostic"]!;
                diagnostic[field["vm_diagnostic.".Length..]] = JsonValueForContractCallView(value);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(field), field, "Unknown contract call/view response field.");
        }

        return response.ToJsonString();
    }

