    private static string ContractStateResponseJson(JsonObject[] entries)
    {
        var entryArray = new JsonArray();
        foreach (var entry in entries)
        {
            entryArray.Add(entry);
        }

        return new JsonObject
        {
            ["entries"] = entryArray,
            ["offset"] = 0,
            ["limit"] = entries.Length,
        }.ToJsonString();
    }

    private static string ContractStateResponseJson(string field, object? value)
    {
        var entry = ContractStateEntryJson("balances/alice", "AQIDBA==", 4);
        entry["decode_error"] = null;
        var entries = new JsonArray(entry);
        var response = new JsonObject
        {
            ["path"] = "balances/alice",
            ["paths"] = new JsonArray("balances/alice"),
            ["prefix"] = null,
            ["entries"] = entries,
            ["offset"] = 0,
            ["limit"] = 1,
            ["next_offset"] = null,
        };

        switch (field)
        {
            case "path":
            case "prefix":
            case "paths":
            case "entries":
            case "offset":
            case "limit":
            case "next_offset":
                response[field] = JsonValueForContractState(value);
                break;
            case "paths[0]":
                ((JsonArray)response["paths"]!)[0] = JsonValueForContractState(value);
                break;
            case "entries[0]":
                entries[0] = JsonValueForContractState(value);
                break;
            case "entries[0].path":
                entry["path"] = JsonValueForContractState(value);
                break;
            case "entries[0].decode_error":
                entry["decode_error"] = JsonValueForContractState(value);
                break;
            case "entries[0].found":
                entry["found"] = JsonValueForContractState(value);
                break;
            case "entries[0].value_b64":
                entry["value_b64"] = JsonValueForContractState(value);
                break;
            case "entries[0].value_len":
                entry["value_len"] = JsonValueForContractState(value);
                break;
            case "entries[0].value_json":
                entry["found"] = false;
                entry.Remove("value_b64");
                entry.Remove("value_len");
                entry["value_json"] = JsonValueForContractState(value);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(field), field, "Unknown contract state response field.");
        }

        return response.ToJsonString();
    }

