    private static string ContractStateResponseEntryUnknownExtensionDuplicateJson()
    {
        var json = ContractStateResponseJson("path", "balances/alice");
        const string marker = "\"decode_error\":null";
        var index = json.IndexOf(marker, StringComparison.Ordinal);
        if (index < 0)
        {
            throw new InvalidOperationException("Contract state fixture is missing the nested decode error.");
        }

        return json.Insert(index + marker.Length, ",\"audit\":{\"nonce\":1,\"nonce\":2}");
    }

