    private static Task InvokeToriiTransactionHashResponseOperationAsync(
        ToriiClient client,
        string operation)
    {
        return operation switch
        {
            "contract-call" => client.CallContractAsync(ValidContractCallRequest()),
            "multisig-contract-propose" => client.ProposeMultisigContractCallAsync(ValidMultisigContractCallProposeRequest()),
            "multisig-contract-approve" => client.ApproveMultisigContractCallAsync(ValidMultisigContractCallApproveRequest()),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown Torii transaction hash response operation."),
        };
    }

    private static string ToriiTransactionHashResponseJson(
        string operation,
        string field,
        string value)
    {
        if (string.Equals(operation, "contract-call", StringComparison.Ordinal))
        {
            var response = ContractCallResponseJsonObject();
            response[field] = value;
            return response.ToJsonString();
        }

        return new JsonObject
        {
            ["ok"] = true,
            ["account_id"] = OnboardingAccountId,
            ["uaid"] = "uaid:0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
            ["asset_definition_id"] = "rose#wonderland",
            ["asset_id"] = $"rose#wonderland#{FaucetAccountId}",
            ["amount"] = "100",
            ["status"] = "QUEUED",
            ["resolved_multisig_account_id"] = CanonicalAccountId,
            ["submitted"] = false,
            ["dataspace"] = "universal",
            ["contract_address"] = "iroha1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq",
            ["code_hash_hex"] = ContractCodeHashHex,
            ["abi_hash_hex"] = ContractAbiHashHex,
            ["creation_time_ms"] = 321,
            ["tx_hash_hex"] = field == "tx_hash_hex" ? value : ToriiTransactionHashHex,
            ["executed_tx_hash_hex"] = field == "executed_tx_hash_hex" ? value : null,
            ["signing_message_b64"] = "bXVsdGlzaWc=",
            ["entrypoint"] = "main",
            ["operation_receipt"] = ContractCallOperationReceiptJsonObject(),
        }.ToJsonString();
    }

    private static (string TransactionPayloadBase64, string SigningMessageBase64) MultisigTransactionDraft(
        string signerAccountId,
        ulong creationTimeMilliseconds,
        FeePaymentIntent feePayment,
        IReadOnlyList<TransactionInstruction>? instructions = null,
        IReadOnlyDictionary<string, JsonNode?>? metadata = null)
    {
        var builder = new TransactionBuilder(
                NetworkId.Parse(CanonicalNetworkId),
                signerAccountId,
                feePayment)
            .SetCreationTimeMilliseconds(creationTimeMilliseconds);
        foreach (var instruction in instructions
            ?? [TransactionInstruction.ExecuteTrigger("multisig-test-draft")])
        {
            builder.AddInstruction(instruction);
        }
        if (metadata is not null)
        {
            builder.ReplaceMetadata(metadata);
        }
        var encoding = new TransactionEncodingContext(signerAccountId);
        var payload = builder.BuildPayloadBytes(encoding, creationTimeMilliseconds);
        return (
            Convert.ToBase64String(payload),
            Convert.ToBase64String(IrohaHash.Hash(payload)));
    }

    private static byte[] InsertRetiredAdmissionIntent(
        byte[] payload,
        uint retiredAdmissionIntent,
        TransactionEncodingContext encoding)
    {
        var reader = new CanonicalNoritoReader(
            payload,
            "test transaction payload",
            nameof(payload));
        var writer = new CanonicalNoritoWriter();
        for (var index = 0; index < 9; index++)
        {
            var field = reader.ReadField($"field_{index}");
            if (index == 7)
            {
                writer.WriteField(encoding.EncodeUInt32(retiredAdmissionIntent));
            }
            writer.WriteField(field);
        }
        reader.RequireEnd();
        return writer.ToArray();
    }

