    private static JsonNode? JsonValueForVpnResponse(object? value)
    {
        return value switch
        {
            null => null,
            string text => JsonValue.Create(text),
            bool boolean => JsonValue.Create(boolean),
            int number => JsonValue.Create(number),
            long number => JsonValue.Create(number),
            ulong number => JsonValue.Create(number),
            _ => throw new ArgumentOutOfRangeException(nameof(value), value, "Unsupported VPN response JSON value."),
        };
    }

