    private static string VpnResponseJson(string operation, string field, string value)
    {
        var relayTlsSpkiSha256Hex = VpnSpkiSha256Hex;
        var relayMldsa65PublicKeyHex = VpnRelayMldsa65PublicKeyHex;
        var quoteId = VpnQuoteIdHex;
        var quoteLeaseIdHex = VpnQuoteIdHex;
        var quoteSessionIdHex = VpnQuoteSessionIdHex;
        var meteringPublicKeyHex = VpnMeteringPublicKeyHex;
        var openLeasePayloadHex = "abcd";
        var sessionId = VpnSessionIdHex;
        var paymentTxHash = VpnPaymentTransactionHashHex;
        var helperTicketHex = VpnHelperTicketHex;
        var receiptLeaseIdHex = VpnQuoteIdHex;
        var settleLeasePayloadHex = "cafe";

        switch ((operation, field))
        {
            case (_, "relay_tls_spki_sha256_hex"):
                relayTlsSpkiSha256Hex = value;
                break;
            case (_, "relay_mldsa65_public_key_hex"):
                relayMldsa65PublicKeyHex = value;
                break;
            case ("quote", "quote_id"):
                quoteId = value;
                break;
            case ("quote", "lease_id_hex"):
                quoteLeaseIdHex = value;
                break;
            case ("quote", "session_id_hex"):
                quoteSessionIdHex = value;
                break;
            case ("quote", "metering_public_key_hex"):
                meteringPublicKeyHex = value;
                break;
            case ("quote", "open_lease_instruction.payload_hex"):
                openLeasePayloadHex = value;
                break;
            case ("session-create", "session_id"):
            case ("session-get", "session_id"):
            case ("receipt-submit", "session_id"):
                sessionId = value;
                break;
            case ("session-create", "quote_id"):
            case ("session-get", "quote_id"):
            case ("receipt-submit", "quote_id"):
                quoteId = value;
                break;
            case ("session-create", "payment_tx_hash"):
            case ("session-get", "payment_tx_hash"):
            case ("receipt-submit", "payment_tx_hash"):
            case ("receipt-list", "items[0].payment_tx_hash"):
                paymentTxHash = value;
                break;
            case ("session-create", "helper_ticket_hex"):
            case ("session-get", "helper_ticket_hex"):
                helperTicketHex = value;
                break;
            case ("receipt-submit", "lease_id_hex"):
            case ("receipt-list", "lease_id_hex"):
                receiptLeaseIdHex = value;
                break;
            case ("receipt-submit", "settle_lease_instruction.payload_hex"):
            case ("receipt-list", "settle_lease_instruction.payload_hex"):
                settleLeasePayloadHex = value;
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(field), field, "Unknown VPN response field.");
        }

        return operation switch
        {
            "profile" => VpnProfileResponseJsonObject(
                relayTlsSpkiSha256Hex,
                relayMldsa65PublicKeyHex).ToJsonString(),
            "quote" => new JsonObject
            {
                ["quote_id"] = quoteId,
                ["lease_id_hex"] = quoteLeaseIdHex,
                ["session_id_hex"] = quoteSessionIdHex,
                ["payment_reference"] = VpnQuoteIdHex,
                ["account_id"] = VpnAccountId,
                ["exit_class"] = "standard",
                ["relay_endpoint"] = "/dns4/vpn.sora.org/udp/443/quic",
                ["lease_secs"] = 3600,
                ["quote_expires_at_ms"] = 1700000000000,
                ["fee_asset_id"] = "xor#universal.universal",
                ["escrow_account_id"] = VpnEscrowAccountId,
                ["operator_account_id"] = VpnOperatorAccountId,
                ["lease_fee"] = "1000000.25",
                ["route_pushes"] = new JsonArray("10.0.0.0/8"),
                ["excluded_routes"] = new JsonArray("127.0.0.0/8"),
                ["dns_servers"] = new JsonArray("1.1.1.1"),
                ["tunnel_addresses"] = new JsonArray("10.208.0.2/32"),
                ["mtu_bytes"] = 1280,
                ["meter_family"] = "vpn-standard",
                ["flow_label_bits"] = 24,
                ["padding_budget_ms"] = 80,
                ["relay_id_hex"] = VpnRelayIdHex,
                ["relay_mldsa65_public_key_hex"] = relayMldsa65PublicKeyHex,
                ["descriptor_commit_hex"] = VpnDescriptorCommitHex,
                ["tls_server_name"] = "vpn.sora.org",
                ["relay_tls_spki_sha256_hex"] = relayTlsSpkiSha256Hex,
                ["relay_certificate_sha256_hex"] = VpnRelayCertificateSha256Hex,
                ["directory_snapshot_digest_hex"] = VpnDirectorySnapshotDigestHex,
                ["metering_public_key_hex"] = meteringPublicKeyHex,
                ["open_lease_instruction"] = VpnTxInstructionJson("OpenVpnLeaseEscrow", openLeasePayloadHex),
            }.ToJsonString(),
            "session-create" or "session-get" => VpnSessionResponseJson(
                sessionId,
                quoteId,
                paymentTxHash,
                relayTlsSpkiSha256Hex,
                helperTicketHex,
                relayMldsa65PublicKeyHex),
            "receipt-submit" => VpnReceiptResponseJson(
                sessionId,
                quoteId,
                paymentTxHash,
                receiptLeaseIdHex,
                settleLeasePayloadHex),
            "receipt-list" => new JsonObject
            {
                ["items"] = new JsonArray(JsonNode.Parse(VpnReceiptResponseJson(
                    sessionId,
                    quoteId,
                    paymentTxHash,
                    receiptLeaseIdHex,
                    settleLeasePayloadHex))),
                ["total"] = 1,
            }.ToJsonString(),
            _ => throw new ArgumentOutOfRangeException(nameof(operation), operation, "Unknown VPN response operation."),
        };
    }

