    public static IEnumerable<object[]> MalformedIdentifierResolveEnvelopeJson()
    {
        const string signedAttestation = """{"kind":"signed","signature":"ABCD"}""";

        yield return new object[]
        {
            $$"""{"payload": {{IdentifierResolvePayloadJson()}}}""",
            "attestation",
            "required",
        };
        yield return new object[]
        {
            $$"""{"attestation": {{signedAttestation}}}""",
            "payload",
            "required",
        };
        yield return new object[]
        {
            IdentifierResolveEnvelopeJson(
                IdentifierResolvePayloadJson(executedAtJson: "-1"),
                signedAttestation),
            "executed_at_ms",
            "non-negative",
        };
        yield return new object[]
        {
            IdentifierResolveEnvelopeJson(
                IdentifierResolvePayloadJson(expiresAtJson: "1710003600000.5"),
                signedAttestation),
            "expires_at_ms",
            "integer",
        };
        yield return new object[]
        {
            $$"""
              {
                "payload": {{IdentifierResolvePayloadJson()}},
                "attestation": {{signedAttestation}},
                "signature_payload_hex": "DEADBEEF"
              }
              """,
            "signature_payload_hex",
            "current payload/attestation envelope",
        };
    }

    private static string VerifyingKeyCommitmentHex(string backend, byte[] bytes)
    {
        var domainBytes = Encoding.UTF8.GetBytes("iroha:zk:v1:vk");
        var backendBytes = Encoding.UTF8.GetBytes(backend);
        var preimage = new byte[domainBytes.Length + 8 + backendBytes.Length + 8 + bytes.Length];
        var offset = 0;
        Buffer.BlockCopy(domainBytes, 0, preimage, offset, domainBytes.Length);
        offset += domainBytes.Length;
        WriteUInt64BigEndian(preimage, offset, (ulong)backendBytes.Length);
        offset += 8;
        Buffer.BlockCopy(backendBytes, 0, preimage, offset, backendBytes.Length);
        offset += backendBytes.Length;
        WriteUInt64BigEndian(preimage, offset, (ulong)bytes.Length);
        offset += 8;
        Buffer.BlockCopy(bytes, 0, preimage, offset, bytes.Length);
        return Convert.ToHexString(SHA256.HashData(preimage)).ToLowerInvariant();
    }

    private static string TestAccountId(byte seedByte)
    {
        var seed = new byte[Ed25519Signer.PrivateKeySeedLength];
        Array.Fill(seed, seedByte);
        return AccountAddress
            .FromPublicKey(Ed25519Signer.GetPublicKey(seed))
            .ToI105(AccountAddress.DefaultChainDiscriminant);
    }

    private sealed class RecordingHandler : HttpMessageHandler
    {
        private readonly Func<HttpRequestMessage, HttpResponseMessage> responder;

        public RecordingHandler(Func<HttpRequestMessage, HttpResponseMessage> responder)
        {
            this.responder = responder;
        }

        public HttpRequestMessage? LastRequest { get; private set; }

        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
        {
            LastRequest = request;
            var response = responder(request);
            response.RequestMessage ??= request;
            return Task.FromResult(response);
        }
    }

}
